namespace sv_9016c5effee7407eb62520732afa32b7.Auth;

/// <summary>
/// Shared DTO used to persist authentication state from server to WebAssembly client.
/// </summary>
public sealed class UserInfo
{
    public string Name { get; set; } = "";
    public string Email { get; set; } = "";
    public string[] Roles { get; set; } = [];
}

using System.Security.Claims;
using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Authorization;
using Microsoft.AspNetCore.Components.Web;

namespace sv_9016c5effee7407eb62520732afa32b7.Auth;

/// <summary>
/// Server-side AuthenticationStateProvider that simulates a logged-in user
/// and persists the authentication state so the WebAssembly runtime can pick it up.
/// </summary>
public sealed class ServerAuthenticationStateProvider : AuthenticationStateProvider, IDisposable
{
    private readonly PersistentComponentState _persistentState;
    private readonly PersistingComponentStateSubscription _subscription;
    private readonly Task<AuthenticationState> _authStateTask;

    public ServerAuthenticationStateProvider(PersistentComponentState persistentState)
    {
