9. /// authentication state from the server via PersistentComponentState.
10. /// </summary>
11. public sealed class ClientAuthenticationStateProvider : AuthenticationStateProvider
12. {
13.     private static readonly Task<AuthenticationState> _unauthenticated =
14.         Task.FromResult(new AuthenticationState(new ClaimsPrincipal(new ClaimsIdentity())));
