18.     public ClientAuthenticationStateProvider(PersistentComponentState persistentState)
19.     {
20.         if (persistentState.TryTakeFromJson<UserInfo>("UserInfo", out var userInfo) && userInfo is not null)
21.         {
22.             var claims = new List<Claim>
23.             {
24.                 new(ClaimTypes.Name, userInfo.Name),
25.                 new(ClaimTypes.Email, userInfo.Email),
26.             };
27. 
28.             foreach (var role in userInfo.Roles)
29.             {
